import{_ as p,a0 as o,w as i,s as u,ao as l,I as a,x as e,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"理解开源安全中的林纳斯定律 | LCTT x X-CMD","titleTemplate":false,"description":"理解开源安全中的林纳斯定律 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理解开源安全中的林纳斯定律 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理解开源安全中的林纳斯定律 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20210209 Understanding Linus-s Law for open source security","title":"理解开源安全中的林纳斯定律","tag":"202212","desc":""},"relativePath":"202212/20210209 Understanding Linus-s Law for open source security.md","filePath":"[post].md"}'),d={name:"202212/20210209 Understanding Linus-s Law for open source security.md"};function m(f,t,T,b,C,x){const r=o("Link");return i(),u("div",null,[t[21]||(t[21]=l('<h1 id="理解开源安全中的林纳斯定律" tabindex="-1">理解开源安全中的林纳斯定律 <a class="header-anchor" href="#理解开源安全中的林纳斯定律" aria-label="Permalink to “理解开源安全中的林纳斯定律”">​</a></h1><p><ruby>林纳斯定律<rt>Linus&#39;s Law</rt></ruby>即“<ruby>只要有足够多的眼睛关注，任何漏洞都无处隐藏<rt>given enough eyeballs, all bugs are shallow</rt></ruby>”。那么林纳斯定律是如何应用于开源软件安全的呢？</p><p><img src="https://img.linux.net.cn/data/attachment/album/202212/13/114637dg6w34suucuupucv.jpg" alt=""></p><p>这篇文章讨论 Linux 对开源软件安全的影响。</p><p>开源软件的一个常被赞扬的优点是它的代码能够被任何人审查（安全专家通常称之为“代码审计”）。然而，如果你真的去问很多开源软件用户他们上一次检查代码是什么时候。你大概只能收获他们茫然的眼神或者是喃喃的低语。此外，对于一些相当大型的开源应用，有效地审查每一行代码也是困难的。</p><p>根据上述这些稍显不安的事实，我们不得不思考：如果没有人察看这些代码，它是开源还是闭源真的有关系吗？</p><h3 id="你应该相信开源吗" tabindex="-1">你应该相信开源吗？ <a class="header-anchor" href="#你应该相信开源吗" aria-label="Permalink to “你应该相信开源吗？”">​</a></h3><p>计算机爱好者倾向于作出认为开源软件比其他软件更加安全的传统假设。我们通常不会讨论这意味者什么：比较的基础是什么（比什么“更”安全？），或者上述结论是如何得到的。这是一个危险的陈述，因为它表明只要你将一些东西称之为“开源”，它就自动如魔法般地继承了更高的安全性。这不是开源，事实上，这正是开源安全非常反对的。</p><p>除非你已经亲自审计并理解了软件代码，否则就不应该假定一个应用程序是安全的。一但你做到了这一点，就可以给予它 <ruby>终极信任<rt>ultimate trust</rt></ruby>。<em>终极信任</em> 不是对计算机而言的，而是对你本人而言的，至少在这一应用程序被渗透攻击之前，你信任它是因为你选择了相信它是安全的。</p><p>使用者本人是唯一可以对软件代码给予终极信任的人，因此任何人想要获得这样的享受都必须亲自审查代码。相信其他人的话是不管用的。</p><p>在你已经亲自审计并理解了软件代码之前，你对一个应用程序给予的最大信任度是一个范围，可以是从 <em>根本不信任</em> 到 <em>相当信任</em> 之间。然而我们并没有一个关于信任程度的标准对照表，这是一个你必须亲自做出的个人选择。如果你已经从非常信任的人那里听说了一款应用程序是安全的，那么你可能会更信任这个软件，而不是信任那些你没有得到信任建议的东西。</p><p>然而，因为无法审计专有（闭源）软件代码，你不可能给予它 <em>终极信任</em>。</p><h3 id="林纳斯定律" tabindex="-1">林纳斯定律 <a class="header-anchor" href="#林纳斯定律" aria-label="Permalink to “林纳斯定律”">​</a></h3><p>现实很骨感，并不是每个人都是程序员，同时也不是每个程序员都有时间检查数以万计的代码行。因此如果你没有亲自审查代码，你就只能选择（一定程度上）相信那些 <em>亲自</em> 审查了代码的人。</p><p>那么，有哪些人会审查代码呢？</p><p>林纳斯定律声称 <em>只要有足够的眼睛关注，任何漏洞都无处隐藏</em>，然而我们并不知道多少双眼睛是“足够”的。请不要低估这一数量，应用程序往往经过了远超你想象数量的人员审查。原始开发人员以及后续开发人员显然清楚他们自己写下的代码，不过开源软件往往都是团队成果，开源时间越长，阅读了代码的开发人员越多。新加入的开发人员也必须回顾项目代码的核心部分，因为他们必须学习基础代码以加入新的功能。</p><p>同时，为了使开源软件能够在 Linux 发行版上可用，负责开源软件打包分发的开发人员会加入多个项目。有时一个应用程序可能会在不熟悉项目代码的情况下打包，但是大多数时候，开源软件打包人员都是熟悉所打包的项目代码的。这不仅仅是因为他们不想在他们不信任的软件上签名，还由于他们可能不得不修改代码来使得程序能够正确编译。漏洞报告人员和漏洞修复人员一般也是熟悉代码库的，因为他们需要尝试解决小到运行异常，大到程序崩溃的问题。当然，一些漏洞报告人员不是通过亲自审查项目代码，而是通过关注明显未按预期工作的现象，无意中揭示了代码漏洞。系统管理员通常都是通晓用户依赖的重要应用软件的代码的。最后，还有一些安全研究人员，他们专门深入代码内部以揭露潜在的漏洞。</p><h3 id="信任与透明" tabindex="-1">信任与透明 <a class="header-anchor" href="#信任与透明" aria-label="Permalink to “信任与透明”">​</a></h3><p>很多人先入为主的认为大型软件的审计是基本不可能的，因为它由数以万计的代码行组成。不要被软件运行所需的代码量欺骗了。我们不需要真的阅读数以万计的代码行。代码是高度结构化的，可被利用的代码漏洞仅仅只是其中的一行，不过它通常影响软件的全部功能。</p><p>当然，也有例外。有时仅仅一个系统调用或者链接一个有缺陷的库文件就可能引入一系列漏洞。幸运的是，多亏安全研究人员以及漏洞数据库所扮演的积极角色，这些错误相对而言是容易发现的。</p>',20)),a("p",null,[t[2]||(t[2]=e("一些人指着错误追踪系统，比如 ",-1)),a("ruby",null,[n(r,{href:"https://cve.mitre.org"},{default:s(()=>[...t[0]||(t[0]=[e("通用漏洞披露",-1)])]),_:1}),t[1]||(t[1]=a("rt",null,"Common Vulnerabilities and Exposures",-1))]),t[3]||(t[3]=e("（CVE）网站，并推断开源软件显而易见是不安全的。毕竟已经向公众公开了大量的安全风险，涉及许多开源项目。但是不要被数据欺骗了。只是因为我们看不到现闭源软件的漏洞，并不意味着闭源软件中不存在漏洞。事实上，已经有很多针对闭源软件的漏洞攻击提出了，闭源软件也是存在漏洞的。区别在于开发者（以及用户）可以查看开源软件的 ",-1)),t[4]||(t[4]=a("em",null,"所有的漏洞",-1)),t[5]||(t[5]=e(" 从而降低漏洞的影响。这是扩大对开源软件信任的系统机制的一部分，却正是闭源软件软件所缺少的。",-1))]),t[22]||(t[22]=l('<p>对于任何代码而言，可能永远没有“足够的眼睛”来发现漏洞，但是开发社区越壮大、越多样化，越有机会发现和修复代码中的缺陷。</p><h3 id="信任与人" tabindex="-1">信任与人 <a class="header-anchor" href="#信任与人" aria-label="Permalink to “信任与人”">​</a></h3><p>在开源社区中，参与同一项目的众多开发者已经发现“不安全”的漏洞，却保持沉默的的可能性是微乎其微的，因为人们很少同意以这样的方式合谋。我们已经看到了在应对 COVID-19 的过程中，人类的行为是如何不一致了，在这里也一样：</p><ul><li>我们都发现了漏洞（病毒）。</li><li>我们知晓如何避免它传播（待在家里）。</li><li>然而病毒还是在持续传播，因为总是有一个或者多个人偏离了消减疫情的计划。</li></ul><p>开源软件中的漏洞也一样，如果有人发现了漏洞总会公之于众（当然，我们说的是“假如”能够发现）。</p><p>然而就专有软件而言，有很大可能参与项目的众多开发者即使注意到不安全的漏洞却仍然保持沉默，因为专有模式依赖于薪水。如果一个开发者将漏洞泄漏出来，他可能只是伤害了该专有软件的声誉，进而降低软件的销售额；或者，在更糟糕的情况下，他可能因此而丢了工作。开发人员拿着薪水秘密地研究软件，往往不会谈论其缺陷。如果你曾经是一名开发者，你可能曾经签署过 NDA （LCTT 译注：<ruby>保密协议<rt>Non-Disclosure Agreement</rt></ruby>），也被培训过商业秘密的重要性，等等不一而足。专有软件鼓励在面对严重的秘密缺陷时保持沉默，更多时候甚至是强制要求沉默。</p><h3 id="信任与软件" tabindex="-1">信任与软件 <a class="header-anchor" href="#信任与软件" aria-label="Permalink to “信任与软件”">​</a></h3><p>不要信任未经你审计的软件。</p><p>如果你必须相信未经你审计的软件，那么选择相信已经面向那些更有可能将软件缺陷公之于众的开发者公开代码的软件。</p><p>开源软件并没有比专有软件继承更高的安全性，但是修复它的系统得到了更好的规划、实施和人员配置。</p><hr>',11)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),n(r,{href:"https://opensource.com/article/21/2/open-source-security"},{default:s(()=>[...t[6]||(t[6]=[e("https://opensource.com/article/21/2/open-source-security",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("作者：",-1)),n(r,{href:"https://opensource.com/users/seth"},{default:s(()=>[...t[8]||(t[8]=[e("Seth Kenlon",-1)])]),_:1}),t[13]||(t[13]=e(" 选题：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[9]||(t[9]=[e("lujun9972",-1)])]),_:1}),t[14]||(t[14]=e(" 译者：",-1)),n(r,{href:"https://github.com/CanYellow"},{default:s(()=>[...t[10]||(t[10]=[e("CanYellow",-1)])]),_:1}),t[15]||(t[15]=e(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:s(()=>[...t[17]||(t[17]=[e("Linux中国",-1)])]),_:1}),t[20]||(t[20]=e(" 荣誉推出",-1))])])}const y=p(d,[["render",m]]);export{h as __pageData,y as default};
